struct Params { count: u32, seed: u32, bins: u32, pad: u32 };

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> values: array<u32>;
@group(0) @binding(2) var<storage, read_write> hist: array<atomic<u32>>;

@compute @workgroup_size(256)
fn generate(@builtin(global_invocation_id) gid: vec3<u32>,
            @builtin(num_workgroups) nwg: vec3<u32>) {
    let i = gid.y * nwg.x * 256u + gid.x;
    if (i >= params.count) { return; }
    let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
    let b = (a * a + a * 37u + 11u) % 40009u;
    let c = (b * 613u + 7919u) % 40009u;
    let d = (c + (i / 40000u) * 7919u) % 40009u;
    values[i] = d % 1000u;
}

@compute @workgroup_size(256)
fn count(@builtin(global_invocation_id) gid: vec3<u32>,
         @builtin(num_workgroups) nwg: vec3<u32>) {
    let i = gid.y * nwg.x * 256u + gid.x;
    if (i >= params.count) { return; }
    let bin = values[i] * params.bins / 1000u;
    atomicAdd(&hist[bin], 1u);
}
"""


def main():
    with open(sys.argv[1]) as f:
        count, seed, bins = (int(x) for x in f.read().split())

    counts = np.zeros(bins, dtype=np.uint32)
    if count > 0:
        device = wgpu.utils.get_default_device()
        module = device.create_shader_module(code=SHADER)
        usage = wgpu.BufferUsage
        params = device.create_buffer_with_data(
            data=struct.pack("<4I", count, seed, bins, 0),
            usage=usage.UNIFORM,
        )
        values = device.create_buffer(size=count * 4, usage=usage.STORAGE)
        hist = device.create_buffer(
            size=256 * 4, usage=usage.STORAGE | usage.COPY_SRC | usage.COPY_DST
        )
        device.queue.write_buffer(hist, 0, bytes(256 * 4))

        layout = device.create_bind_group_layout(entries=[
            {"binding": 0, "visibility": wgpu.ShaderStage.COMPUTE,
             "buffer": {"type": wgpu.BufferBindingType.uniform}},
            {"binding": 1, "visibility": wgpu.ShaderStage.COMPUTE,
             "buffer": {"type": wgpu.BufferBindingType.storage}},
            {"binding": 2, "visibility": wgpu.ShaderStage.COMPUTE,
             "buffer": {"type": wgpu.BufferBindingType.storage}},
        ])
        pl = device.create_pipeline_layout(bind_group_layouts=[layout])
        bg = device.create_bind_group(layout=layout, entries=[
            {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": 16}},
            {"binding": 1, "resource": {"buffer": values, "offset": 0, "size": count * 4}},
            {"binding": 2, "resource": {"buffer": hist, "offset": 0, "size": 256 * 4}},
        ])
        gen = device.create_compute_pipeline(
            layout=pl, compute={"module": module, "entry_point": "generate"})
        cnt = device.create_compute_pipeline(
            layout=pl, compute={"module": module, "entry_point": "count"})

        groups = (count + 255) // 256
        gx = min(groups, 4096)
        gy = (groups + gx - 1) // gx  # gx*gy*256 >= count

        enc = device.create_command_encoder()
        for pipe in (gen, cnt):
            p = enc.begin_compute_pass()
            p.set_pipeline(pipe)
            p.set_bind_group(0, bg)
            p.dispatch_workgroups(gx, gy, 1)
            p.end()
        device.queue.submit([enc.finish()])

        raw = device.queue.read_buffer(hist)
        counts = np.frombuffer(raw, dtype=np.uint32)[:bins]

    out = [f"BIN {i} {int(c)}" for i, c in enumerate(counts)]
    out.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
